public async Task<byte[]> FetchAsync(string url)
{
    string[] allowedHosts = ["avatars.example.com"];
    if (!Uri.TryCreate(url, UriKind.Absolute, out var uri) || uri.Scheme != Uri.UriSchemeHttps || !allowedHosts.Contains(uri.Host, StringComparer.OrdinalIgnoreCase))
        throw new ArgumentException("avatar URL must be https on an allowed host", nameof(url));
    return await _http.GetByteArrayAsync(uri);
}

