public async Task FetchAsync_refuses_internal_addresses_without_a_request()
{
    var handler = new FakeHandler();
    var fetcher = new AvatarFetcher(new HttpClient(handler));
    await Assert.ThrowsAsync<ArgumentException>(() => fetcher.FetchAsync("http://169.254.169.254/latest/meta-data/"));
    Assert.Empty(handler.Requests);
}
